import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BzWmN0d8.js";const u=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md","lastUpdated":1788425513000}'),i={name:"guide/benchmarks.md"};function s(n,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p><code>lograil</code> is built to stay cheap on the hot path (the code that runs every time you log). This page explains how to measure throughput yourself and documents the optimizations that keep the core fast.</p><h2 id="running-the-benchmarks" tabindex="-1">Running the benchmarks <a class="header-anchor" href="#running-the-benchmarks" aria-label="Permalink to &quot;Running the benchmarks&quot;">​</a></h2><p>Benchmarks use <a href="https://vitest.dev/api/#benchmark" target="_blank" rel="noreferrer">vitest bench</a>. Run them from the repo root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # or: npx vitest bench --run</span></span></code></pre></div><p>Each case reports <strong>hz</strong> (operations per second) — higher is better — plus latency percentiles. The suite isolates the logger core from transport I/O by pairing the logger with a no-op (do-nothing) transport, so the numbers reflect formatting, filtering and entry construction rather than disk/console cost.</p><h2 id="throughput-indicative" tabindex="-1">Throughput (indicative) <a class="header-anchor" href="#throughput-indicative" aria-label="Permalink to &quot;Throughput (indicative)&quot;">​</a></h2><p>Measured on Node.js v24 (x64) with the no-op (do-nothing) transport. Numbers vary by machine and will drift run to run — treat them as <strong>relative</strong> comparisons, not guarantees. Rerun <code>npm run bench</code> on your own hardware for authoritative figures.</p><table tabindex="0"><thead><tr><th>Case</th><th>Throughput</th></tr></thead><tbody><tr><td><code>emit</code> — filtered-out debug (early return)</td><td>~19.5M ops/s</td></tr><tr><td><code>emit</code> — <code>info</code> + pass-through (identity) formatter (no format cost)</td><td>~3.0M ops/s</td></tr><tr><td><code>emit</code> — <code>info</code> + line formatter</td><td>~1.46M ops/s</td></tr><tr><td>line formatter (standalone call)</td><td>~1.96M ops/s</td></tr><tr><td>JSON formatter (standalone call)</td><td>~1.23M ops/s</td></tr></tbody></table><h2 id="comparison-with-pino" tabindex="-1">Comparison with <code>pino</code> <a class="header-anchor" href="#comparison-with-pino" aria-label="Permalink to &quot;Comparison with `pino`&quot;">​</a></h2><p><code>pino</code> is the go-to ultra-fast logger for <strong>pure Node.js</strong>. <code>lograil</code> targets a different envelope — Electron (main + renderer) and the Web — so a raw Node throughput race is only half the story. The table is a <strong>capability</strong> comparison; for raw ops/sec rerun <code>npm run bench</code> and compare against <code>pino</code> on your hardware.</p><table tabindex="0"><thead><tr><th>Dimension</th><th><code>lograil</code></th><th><code>pino</code></th></tr></thead><tbody><tr><td>Runtime</td><td>Electron main, Electron renderer, Web, Node</td><td>Node only</td></tr><tr><td>Cross-process logs</td><td>first-class (<code>ElectronIpcTransport</code>, structured cloning)</td><td>needs manual IPC</td></tr><tr><td>Structured <code>context</code>/<code>metadata</code> + <code>args</code></td><td>built-in, frozen immutable entry</td><td>bound objects / <code>child</code> bindings</td></tr><tr><td>Processor / plugin pipeline</td><td>built-in (<code>Filter</code>/<code>Processor</code>/<code>Plugin</code>)</td><td>via transports / custom</td></tr><tr><td>Built-in redaction &amp; serializers</td><td><code>createRedactProcessor</code> / <code>createDefaultSerializers</code></td><td><code>pino-secret</code> / custom</td></tr><tr><td>OTel trace correlation</td><td><code>createOtelTracePlugin</code></td><td>external</td></tr><tr><td>Formats</td><td>JSON (<code>flatten</code> option) + line</td><td>JSON, pretty, custom</td></tr><tr><td>Raw Node throughput</td><td>very fast (see table above)</td><td>typically faster (C-level buffering)</td></tr><tr><td>Browser / bundle-safe</td><td>yes (Node built-ins stubbed via a <code>shims</code> layer + <code>browser</code> field; verified by bundler integration tests)</td><td>no</td></tr></tbody></table><h3 id="when-to-choose-which" tabindex="-1">When to choose which <a class="header-anchor" href="#when-to-choose-which" aria-label="Permalink to &quot;When to choose which&quot;">​</a></h3><ul><li><strong>Use <code>pino</code></strong> if you log only from a Node server, never touch Electron or the browser, and want the absolute maximum raw throughput with minimal machinery.</li><li><strong>Use <code>lograil</code></strong> if you need any of: Electron main↔renderer log forwarding, Web runtime support, a structured <code>context</code>/<code>metadata</code> model, a plugin/processor pipeline, built-in redaction/serializers, OTel trace correlation, or async per-transport queues with a frozen immutable entry contract.</li></ul><p>You can also mix: keep <code>pino</code> for a hot Node service and use <code>lograil</code> in the Electron shell that talks to it.</p><h2 id="where-these-results-are-published" tabindex="-1">Where these results are published <a class="header-anchor" href="#where-these-results-are-published" aria-label="Permalink to &quot;Where these results are published&quot;">​</a></h2><p>The numbers above are committed to this page and <strong>shipped with the docs</strong> — every <code>yarn docs:build</code> (and the versioned docs deployed on each release) includes them. To refresh them, run <code>npm run bench</code> and paste the <code>hz</code>/latency output into this table. They are intentionally <em>indicative</em>: rerun on your own hardware for authoritative figures.</p><h2 id="what-we-optimized" tabindex="-1">What we optimized <a class="header-anchor" href="#what-we-optimized" aria-label="Permalink to &quot;What we optimized&quot;">​</a></h2><p>The library ships with several hot-path optimizations. None change observable behavior — they are all correctness-preserving.</p><ol><li><strong>Skip the async plugin path when unused.</strong> When no plugin registered an <code>onEntry</code> interceptor, <code>Logger</code> emits synchronously and bypasses the <code>Promise</code>/write-queue machinery entirely (<code>PluginManager.hasEntryInterceptors()</code> gate + a dedicated <code>dispatch</code>). This is what opens the gap between the &quot;filtered-out&quot; and &quot;pass-through (identity) formatter&quot; rows above.</li><li><strong>Cached combined filter.</strong> <code>Pipeline</code> compiles all filters into a single combined filter condition (<code>cachedFilter</code>) and reuses it, so the pipeline avoids re-walking the filter list on every entry.</li><li><strong><code>safeStringify</code> fast path.</strong> Plain JSON-serializable data (objects/arrays/ primitives; <code>undefined</code> included) is serialized with the native <code>JSON</code> methods and skips the custom replacement function that only exists to handle <code>Error</code>, circular refs and <code>BigInt</code>. This keeps the JSON formatter on the fast path for the common case.</li><li><strong><code>isEmptyRecord</code> in the line formatter.</strong> Instead of <code>Object.keys(ctx).length</code> (which allocates an array and iterates), the line formatter uses a cheap <code>for…in</code> presence check to decide whether to render <code>context</code>/<code>metadata</code>.</li><li><strong>Shared frozen empty context.</strong> <code>ContextStore.get()</code> returns one shared frozen empty object when the store is empty, avoiding a per-call clone and allocation on the very common &quot;no context&quot; path. Callers cannot mutate it.</li><li><strong>Reused <code>Date</code> for timestamps.</strong> <code>buildEntry</code> formats the ISO-8601 timestamp from a single reused <code>Date</code> (via UTC getters), so a log line never allocates a fresh <code>Date</code> object. Only the resulting string is built.</li></ol><h2 id="filtering-early-is-the-cheapest-win" tabindex="-1">Filtering early is the cheapest win <a class="header-anchor" href="#filtering-early-is-the-cheapest-win" aria-label="Permalink to &quot;Filtering early is the cheapest win&quot;">​</a></h2><p>The biggest single speedup is simply not logging: the level gate runs before the pipeline, so <code>debug</code> calls below the active threshold are dropped for free. Set the level as high as your environment allows in production.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { logger } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;lograil&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setLevel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// info/debug never enter the pipeline</span></span></code></pre></div>',23)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
